SELECT * FROM inventory_warning
WHERE 1=1

    AND WAREHOUSE_ID = #{warehouseId}


    AND WARNING_LEVEL = #{warningLevel}


    AND STATUS = #{status}

ORDER BY ID DESC

SELECT * FROM inventory_warning
WHERE PRODUCT_ID = #{productId}
AND WAREHOUSE_ID = #{warehouseId}
AND (DELETED = 0 OR DELETED IS NULL)
ORDER BY ID DESC
LIMIT 1
